#[test]
fn test_property_element_by_reference_is_still_refused() {
    let error = compile_source_expect_backend_error_or_type_error(
        r#"<?php
class Box { public array $items = [1, 2, 3]; }
function set9(int &$n): void { $n = 9; }
$c = new Box();
set9($c->items[1]);
"#,
    );
    assert!(
        error.contains("must be passed a variable"),
        "unexpected diagnostic: {error}"
    );
}
'''
